            return item;
        }
    }

    /// <summary>推进一帧：移动 + 出屏回收。</summary>
    public void Tick(double deltaSeconds)
    {
        lock (_lock)
        {
            for (var i = _active.Count - 1; i >= 0; i--)
            {
                var item = _active[i];
                item.X += item.Speed * deltaSeconds;
                if (item.X > _width)
                {
                    _active.RemoveAt(i);
                    _pool.Push(item); // 回池复用
                }
            }
        }
    }
}

